function MillHopperAgitatorMaker.init() MillHopperAgitatorMaker.ironStock=14; MillHopperAgitatorMaker.bronzeStock=12; MillHopperAgitatorMaker.woodStock=14; MillHopperAgitatorMaker.leatherStock=8; MillHopperAgitatorMaker.silverStock=8; MillHopperAgitatorMaker.goldStock=6; MillHopperAgitatorMaker.jewelStock=4; MillHopperAgitatorMaker.pearlStock=4; MillHopperAgitatorMaker.productStock={}; MillHopperAgitatorMaker.buildings={}; MillHopperAgitatorMaker.maker=nil; MillHopperAgitatorMaker.activeMaking={}; MillHopperAgitatorMaker.totalProducts=0; MillHopperAgitatorMaker.dayTimer=0; print("[MillHopperAgitatorMaker] Royal Mill Hopper Agitator Maker System initialized (6 products, 4 buildings)") end
function MillHopperAgitatorMaker.hireMaker(n,s) s=s or math.random(55,90); local c=580+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; MillHopperAgitatorMaker.maker={name=n or ("Stresalec "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Stresalec najet: %s (spretnost: %d)",MillHopperAgitatorMaker.maker.name,s),"success") end; return true end
function MillHopperAgitatorMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function MillHopperAgitatorMaker.build(id) local ok,e=MillHopperAgitatorMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(MillHopperAgitatorMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function MillHopperAgitatorMaker.getQualityBonus() local b=0; for _,bd in ipairs(MillHopperAgitatorMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function MillHopperAgitatorMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and MillHopperAgitatorMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and MillHopperAgitatorMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and MillHopperAgitatorMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and MillHopperAgitatorMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and MillHopperAgitatorMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and MillHopperAgitatorMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and MillHopperAgitatorMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and MillHopperAgitatorMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #MillHopperAgitatorMaker.buildings==0 then return false,"Potrebna stresalna delavnica" end; if not MillHopperAgitatorMaker.maker then return false,"Potreben stresalec" end; return true end
function MillHopperAgitatorMaker.make(pt,qty) qty=qty or 1; local ok,e=MillHopperAgitatorMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then MillHopperAgitatorMaker.ironStock=MillHopperAgitatorMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then MillHopperAgitatorMaker.bronzeStock=MillHopperAgitatorMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then MillHopperAgitatorMaker.woodStock=MillHopperAgitatorMaker.woodStock-d.woodCost*qty end; if d.leatherCost then MillHopperAgitatorMaker.leatherStock=MillHopperAgitatorMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then MillHopperAgitatorMaker.silverStock=MillHopperAgitatorMaker.silverStock-d.silverCost*qty end; if d.goldCost then MillHopperAgitatorMaker.goldStock=MillHopperAgitatorMaker.goldStock-d.goldCost*qty end; if d.jewelCost then MillHopperAgitatorMaker.jewelStock=MillHopperAgitatorMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then MillHopperAgitatorMaker.pearlStock=MillHopperAgitatorMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if MillHopperAgitatorMaker.maker then t=math.max(1,t-math.floor(MillHopperAgitatorMaker.maker.skill/13)) end; table.insert(MillHopperAgitatorMaker.activeMaking,{id="millhopperagitator_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function MillHopperAgitatorMaker.completeMaking(m) local q=1.0+(MillHopperAgitatorMaker.getQualityBonus()/100); if MillHopperAgitatorMaker.maker then q=q+(MillHopperAgitatorMaker.maker.skill/140) end; q=math.min(2.5,q); MillHopperAgitatorMaker.productStock[m.productType]=(MillHopperAgitatorMaker.productStock[m.productType] or 0)+m.quantity; MillHopperAgitatorMaker.totalProducts=MillHopperAgitatorMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if MillHopperAgitatorMaker.maker then MillHopperAgitatorMaker.maker.itemsMade=MillHopperAgitatorMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then MillHopperAgitatorMaker.maker.skill=math.min(100,MillHopperAgitatorMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Stresalec izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"millhopperagitator.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function MillHopperAgitatorMaker.update(dt) if not _G.state then return end; MillHopperAgitatorMaker.dayTimer=MillHopperAgitatorMaker.dayTimer+dt; if MillHopperAgitatorMaker.dayTimer>=30 then MillHopperAgitatorMaker.dayTimer=0; for i=#MillHopperAgitatorMaker.activeMaking,1,-1 do local m=MillHopperAgitatorMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then MillHopperAgitatorMaker.completeMaking(m); table.remove(MillHopperAgitatorMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(MillHopperAgitatorMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if MillHopperAgitatorMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function MillHopperAgitatorMaker.getStats() return {ironStock=MillHopperAgitatorMaker.ironStock,bronzeStock=MillHopperAgitatorMaker.bronzeStock,woodStock=MillHopperAgitatorMaker.woodStock,leatherStock=MillHopperAgitatorMaker.leatherStock,silverStock=MillHopperAgitatorMaker.silverStock,goldStock=MillHopperAgitatorMaker.goldStock,jewelStock=MillHopperAgitatorMaker.jewelStock,pearlStock=MillHopperAgitatorMaker.pearlStock,productStock=MillHopperAgitatorMaker.productStock,numBuildings=#MillHopperAgitatorMaker.buildings,hasMaker=MillHopperAgitatorMaker.maker~=nil,makerName=MillHopperAgitatorMaker.maker and MillHopperAgitatorMaker.maker.name or "—",makerSkill=MillHopperAgitatorMaker.maker and MillHopperAgitatorMaker.maker.skill or 0,activeMaking=#MillHopperAgitatorMaker.activeMaking,totalProducts=MillHopperAgitatorMaker.totalProducts} end
